"use client";

import "../../styles/whatiuse-base.css";
import "../../styles/components/toolbar.css";
import { Toolbar as ToolbarPrimitive } from "@base-ui/react/toolbar";
import { cn } from "../../lib/cn";

export type ToolbarProps = ToolbarPrimitive.Root.Props;
export type ToolbarGroupProps = ToolbarPrimitive.Group.Props;
export type ToolbarButtonProps = ToolbarPrimitive.Button.Props;
export type ToolbarLinkProps = ToolbarPrimitive.Link.Props;
export type ToolbarInputProps = ToolbarPrimitive.Input.Props;
export type ToolbarSeparatorProps = ToolbarPrimitive.Separator.Props;

export function Toolbar({ className, ...props }: ToolbarProps) {
  return <ToolbarPrimitive.Root className={cn("whatiuse-toolbar", className)} {...props} />;
}

export function ToolbarGroup({ className, ...props }: ToolbarGroupProps) {
  return <ToolbarPrimitive.Group className={cn("whatiuse-toolbar__group", className)} {...props} />;
}

export function ToolbarButton({ className, ...props }: ToolbarButtonProps) {
  return <ToolbarPrimitive.Button className={cn("whatiuse-toolbar__button", className)} {...props} />;
}

export function ToolbarLink({ className, ...props }: ToolbarLinkProps) {
  return <ToolbarPrimitive.Link className={cn("whatiuse-toolbar__link", className)} {...props} />;
}

export function ToolbarInput({ className, ...props }: ToolbarInputProps) {
  return <ToolbarPrimitive.Input className={cn("whatiuse-toolbar__input", className)} {...props} />;
}

export function ToolbarSeparator({ className, ...props }: ToolbarSeparatorProps) {
  return <ToolbarPrimitive.Separator className={cn("whatiuse-toolbar__separator", className)} {...props} />;
}

/* Generated from src/foundation.css and src/styles.css. Do not edit directly. */

@layer whatiuse.tokens, whatiuse.base, whatiuse.components;

@layer whatiuse.components {
.whatiuse-toolbar {
  display: inline-flex;
  min-width: 0;
  min-height: 36px;
  align-items: center;
  gap: 3px;
  padding: 3px;
  border-radius: 8px;
  background: var(--whatiuse-bg-stage);
  color: var(--whatiuse-fg-default);
}

.whatiuse-toolbar[data-orientation="vertical"] { flex-direction: column; align-items: stretch; }

.whatiuse-toolbar__group { display: inline-flex; align-items: center; gap: 2px; }

.whatiuse-toolbar[data-orientation="vertical"] .whatiuse-toolbar__group { flex-direction: column; align-items: stretch; }

.whatiuse-toolbar__button,
.whatiuse-toolbar__link {
  display: inline-flex;
  width: 28px;
  height: 28px;
  align-items: center;
  justify-content: center;
  padding: 0;
  border: 0;
  border-radius: 6px;
  outline: 0;
  background: transparent;
  color: var(--whatiuse-fg-muted);
  font: inherit;
  font-size: var(--whatiuse-type-label);
  text-decoration: none;
  cursor: pointer;
  transition: background-color var(--whatiuse-hover-duration), color var(--whatiuse-hover-duration), transform var(--whatiuse-press-duration) var(--whatiuse-ease-out);
}

.whatiuse-toolbar__button svg,
.whatiuse-toolbar__link svg { width: 14px; height: 14px; }

.whatiuse-toolbar__button:hover:not(:disabled),
.whatiuse-toolbar__link:hover { background: var(--whatiuse-hover); color: var(--whatiuse-fg-default); }

.whatiuse-toolbar__button:active:not(:disabled),
.whatiuse-toolbar__link:active { transform: scale(.97); }

.whatiuse-toolbar__button:focus-visible,
.whatiuse-toolbar__link:focus-visible { background: var(--whatiuse-hover); box-shadow: 0 0 0 2px var(--whatiuse-focus-halo); color: var(--whatiuse-fg-default); }

.whatiuse-toolbar__button[data-popup-open],
.whatiuse-toolbar__button[aria-pressed="true"] { background: var(--whatiuse-active); color: var(--whatiuse-fg-default); }

.whatiuse-toolbar__button:disabled { color: var(--whatiuse-fg-disabled); cursor: not-allowed; }

.whatiuse-toolbar__input {
  width: 116px;
  height: 28px;
  margin-left: 2px;
  padding: 0 7px;
  border: 1px solid var(--whatiuse-control-border);
  border-radius: 6px;
  outline: 0;
  background: var(--whatiuse-bg-control);
  box-shadow: var(--whatiuse-shadow-control);
  color: var(--whatiuse-fg-default);
  font: inherit;
  font-size: var(--whatiuse-type-label);
}

.whatiuse-toolbar__input:focus-visible { border-color: var(--whatiuse-control-border-hover); box-shadow: var(--whatiuse-shadow-control), 0 0 0 2px var(--whatiuse-focus-halo); }

.whatiuse-toolbar__separator { width: 1px; height: 20px; margin: 0 2px; background: var(--whatiuse-separator); }

.whatiuse-toolbar[data-orientation="vertical"] .whatiuse-toolbar__separator { width: auto; height: 1px; margin: 2px 0; }

@media (prefers-reduced-motion: reduce) {
.whatiuse-toolbar__button,
.whatiuse-toolbar__link { transition-duration: 0.01ms; }
}
}
